update public.study_daily_content set phrase_munch_lessons = $j$[{"example":{"ko":"우리 가족은 네 명이에요.","en":"There are four people in my family.","parts":[{"ko":"우리","en":"our (Koreans say \"our\" for \"my\" family)"},{"ko":"가족은","en":"family + topic marker"},{"ko":"네","en":"four (native number, before a counter)"},{"ko":"명이에요","en":"people (counter) + is / are"}],"grammar_note":"이에요/예요 means \"is / are\" after a noun: 이에요 after a consonant, 예요 after a vowel."},"practice":{"ko":"제 동생은 학생이에요.","en":"My younger sibling is a student.","parts":[{"ko":"제","en":"my (polite)"},{"ko":"동생은","en":"younger sibling + topic marker"},{"ko":"학생이에요","en":"is a student"}],"choices":["제 동생은 학생이에요.","제 동생은 학생예요.","제 동생을 학생이에요.","제 동생은 학생이 아니에요."]}},{"example":{"ko":"저는 동생이 한 명 있어요.","en":"I have one younger sibling.","parts":[{"ko":"저는","en":"I + topic marker"},{"ko":"동생이","en":"younger sibling + subject marker"},{"ko":"한","en":"one (native number)"},{"ko":"명","en":"counter for people"},{"ko":"있어요","en":"have / there is"}],"grammar_note":"N이/가 있어요 means \"I have N\". The person or thing you have takes 이/가, not 을/를."},"practice":{"ko":"저는 강아지가 있어요.","en":"I have a dog.","parts":[{"ko":"저는","en":"I + topic marker"},{"ko":"강아지가","en":"puppy, dog + subject marker"},{"ko":"있어요","en":"have"}],"choices":["저는 강아지가 있어요.","저는 강아지를 있어요.","저는 강아지가 없어요.","저는 강아지가 있었어요."]}},{"example":{"ko":"아빠는 요리를 좋아해요.","en":"My dad likes cooking.","parts":[{"ko":"아빠는","en":"dad + topic marker"},{"ko":"요리를","en":"cooking + object marker"},{"ko":"좋아해요","en":"likes"}],"grammar_note":"N을/를 좋아해요 means \"likes N\": 을 after a consonant, 를 after a vowel."},"practice":{"ko":"엄마는 영화를 좋아해요.","en":"My mom likes movies.","parts":[{"ko":"엄마는","en":"mom + topic marker"},{"ko":"영화를","en":"movie + object marker"},{"ko":"좋아해요","en":"likes"}],"choices":["엄마는 영화를 좋아해요.","엄마는 영화가 좋아해요.","엄마는 영화를 싫어해요.","엄마는 영화를 좋아했어요."]}}]$j$
 where scheduled_date = '2026-10-26' and level = 'Starter'
   and (phrase_munch_lessons is null or phrase_munch_lessons::text in ('[]', 'null'));
update public.study_daily_content set key_expressions = $j$[{"ko":"~이/가 있어요","rom":"~i/ga isseoyo","en":"I have ~ (a family member)","parts":[{"ko":"~이/가","en":"subject marker on the person: 이 after a consonant, 가 after a vowel"},{"ko":"있어요","en":"have / there is"}],"examples":[{"ko":"저는 동생이 있어요.","en":"I have a younger sibling."},{"ko":"저는 사촌이 많이 있어요.","en":"I have a lot of cousins."}]},{"ko":"~ 명이에요","rom":"~ myeongieyo","en":"there are ~ people","parts":[{"ko":"~","en":"a native Korean number: 세, 네, 다섯…"},{"ko":"명","en":"counter for people"},{"ko":"이에요","en":"is / are"}],"examples":[{"ko":"우리 가족은 네 명이에요.","en":"There are four people in my family."},{"ko":"우리 반 학생은 열 명이에요.","en":"There are ten students in our class."}]},{"ko":"~하고 같이 살아요","rom":"~hago gachi sarayo","en":"I live with ~","parts":[{"ko":"~하고","en":"with (spoken)"},{"ko":"같이","en":"together"},{"ko":"살아요","en":"live"}],"examples":[{"ko":"저는 부모님하고 같이 살아요.","en":"I live with my parents."},{"ko":"저는 할머니하고 같이 살아요.","en":"I live with my grandmother."}]},{"ko":"~을/를 닮았어요","rom":"~eul/reul dalmasseoyo","en":"I look like ~ / I take after ~","parts":[{"ko":"~을/를","en":"the person you look like takes 을/를"},{"ko":"닮았어요","en":"resemble (past form, used for how you are now)"}],"examples":[{"ko":"저는 엄마를 닮았어요.","en":"I look like my mom."},{"ko":"동생은 아빠를 닮았어요.","en":"My younger sibling takes after my dad."}]},{"ko":"~와/과 사이가 좋아요","rom":"~wa/gwa saiga joayo","en":"I get along well with ~","parts":[{"ko":"~와/과","en":"with: 와 after a vowel, 과 after a consonant"},{"ko":"사이가","en":"relationship + subject marker"},{"ko":"좋아요","en":"is good"}],"examples":[{"ko":"저는 동생과 사이가 좋아요.","en":"I get along well with my younger sibling."},{"ko":"아빠는 할아버지와 사이가 좋아요.","en":"My dad gets along well with my grandfather."}]},{"ko":"~을/를 사랑해요","rom":"~eul/reul saranghaeyo","en":"I love ~","parts":[{"ko":"~을/를","en":"object marker on the person you love"},{"ko":"사랑해요","en":"love"}],"examples":[{"ko":"저는 우리 가족을 사랑해요.","en":"I love my family."},{"ko":"저는 우리 강아지를 정말 사랑해요.","en":"I really love our dog."}]}]$j$
 where scheduled_date = '2026-10-26' and level = 'Starter'
   and (key_expressions is null or key_expressions::text in ('[]', 'null'));

update public.study_daily_content set phrase_munch_lessons = $j$[{"example":{"ko":"김치찌개를 제일 좋아해요.","en":"I like kimchi stew the most.","parts":[{"ko":"김치찌개를","en":"kimchi stew + object marker"},{"ko":"제일","en":"the most"},{"ko":"좋아해요","en":"like"}],"grammar_note":"제일 before a verb or adjective means \"the most\": 제일 좋아해요 = like the most."},"practice":{"ko":"불고기를 제일 좋아해요.","en":"I like bulgogi the most.","parts":[{"ko":"불고기를","en":"bulgogi (marinated beef) + object marker"},{"ko":"제일","en":"the most"},{"ko":"좋아해요","en":"like"}],"choices":["불고기를 제일 좋아해요.","불고기가 제일 좋아해요.","불고기를 제일 싫어해요.","불고기를 제일 좋아했어요."]}},{"example":{"ko":"떡볶이는 매워서 맛있어요.","en":"Tteokbokki is tasty because it is spicy.","parts":[{"ko":"떡볶이는","en":"tteokbokki (spicy rice cakes) + topic marker"},{"ko":"매워서","en":"because it is spicy (맵다 + 아서)"},{"ko":"맛있어요","en":"is delicious"}],"grammar_note":"-아/어서 gives the reason: 매워서 = because it is spicy. The reason comes first, the result after."},"practice":{"ko":"냉면은 시원해서 좋아요.","en":"Naengmyeon is good because it is nice and cold.","parts":[{"ko":"냉면은","en":"cold noodles + topic marker"},{"ko":"시원해서","en":"because it is refreshingly cold (시원하다 + 여서)"},{"ko":"좋아요","en":"is good"}],"choices":["냉면은 시원해서 좋아요.","냉면은 시원했어서 좋아요.","냉면은 시원해서 좋았어요.","냉면은 시원하면 좋아요."]}},{"example":{"ko":"피곤할 때 삼계탕을 먹어요.","en":"When I am tired, I eat samgyetang.","parts":[{"ko":"피곤할","en":"tired (피곤하다 + ㄹ)"},{"ko":"때","en":"when"},{"ko":"삼계탕을","en":"ginseng chicken soup + object marker"},{"ko":"먹어요","en":"eat"}],"grammar_note":"-(으)ㄹ 때 means \"when ~\": 피곤할 때 = when I am tired. Add ㄹ after a vowel, 을 after a consonant."},"practice":{"ko":"추울 때 라면을 먹어요.","en":"When it is cold, I eat ramyeon.","parts":[{"ko":"추울","en":"cold (춥다 + ㄹ; ㅂ becomes 우)"},{"ko":"때","en":"when"},{"ko":"라면을","en":"instant noodles + object marker"},{"ko":"먹어요","en":"eat"}],"choices":["추울 때 라면을 먹어요.","춥을 때 라면을 먹어요.","추울 때 라면이 먹어요.","추운 때 라면을 먹어요."]}}]$j$
 where scheduled_date = '2026-10-26' and level = 'Beginner'
   and (phrase_munch_lessons is null or phrase_munch_lessons::text in ('[]', 'null'));
update public.study_daily_content set key_expressions = $j$[{"ko":"~을/를 제일 좋아해요","rom":"~eul/reul jeil joahaeyo","en":"I like ~ the most","parts":[{"ko":"~을/를","en":"object marker on the food"},{"ko":"제일","en":"the most"},{"ko":"좋아해요","en":"like"}],"examples":[{"ko":"저는 김치찌개를 제일 좋아해요.","en":"I like kimchi stew the most."},{"ko":"동생은 치킨을 제일 좋아해요.","en":"My younger sibling likes fried chicken the most."}]},{"ko":"~(으)면 힘이 나요","rom":"~(eu)myeon himi nayo","en":"~ gives me energy","parts":[{"ko":"~(으)면","en":"if / when (I do ~)"},{"ko":"힘이","en":"strength, energy + subject marker"},{"ko":"나요","en":"comes up, appears"}],"examples":[{"ko":"피곤할 때 고기를 먹으면 힘이 나요.","en":"When I am tired, eating meat gives me energy."},{"ko":"아침에 커피를 마시면 힘이 나요.","en":"Drinking coffee in the morning gives me energy."}]},{"ko":"~이/가 입에 맞아요","rom":"~i/ga ibe majayo","en":"~ suits my taste","parts":[{"ko":"~이/가","en":"the food + subject marker"},{"ko":"입에","en":"to (my) mouth"},{"ko":"맞아요","en":"fits, suits"}],"examples":[{"ko":"한국 음식이 입에 맞아요.","en":"Korean food suits my taste."},{"ko":"이 김치는 제 입에 딱 맞아요.","en":"This kimchi is just right for my taste."}]},{"ko":"~을/를 자주 먹어요","rom":"~eul/reul jaju meogeoyo","en":"I often eat ~","parts":[{"ko":"~을/를","en":"object marker on the food"},{"ko":"자주","en":"often"},{"ko":"먹어요","en":"eat"}],"examples":[{"ko":"저는 비빔밥을 자주 먹어요.","en":"I often eat bibimbap."},{"ko":"점심에 김밥을 자주 먹어요.","en":"I often eat gimbap for lunch."}]},{"ko":"~을/를 먹고 싶어요","rom":"~eul/reul meokgo sipeoyo","en":"I want to eat ~","parts":[{"ko":"~을/를","en":"object marker on the food"},{"ko":"먹고","en":"eat (먹다 + 고)"},{"ko":"싶어요","en":"want to"}],"examples":[{"ko":"한국에 가서 떡볶이를 먹고 싶어요.","en":"I want to go to Korea and eat tteokbokki."},{"ko":"오늘은 피자를 먹고 싶어요.","en":"I want to eat pizza today."}]},{"ko":"~(으)ㄴ 음식을 잘 먹어요","rom":"~(eu)n eumsigeul jal meogeoyo","en":"I can eat ~ food well","parts":[{"ko":"~(으)ㄴ","en":"adjective + ㄴ/은 to describe the food"},{"ko":"음식을","en":"food + object marker"},{"ko":"잘 먹어요","en":"eat well, have no trouble eating"}],"examples":[{"ko":"저는 매운 음식을 잘 먹어요.","en":"I can handle spicy food well."},{"ko":"저는 신 음식을 잘 먹어요.","en":"I can handle sour food well."}]}]$j$
 where scheduled_date = '2026-10-26' and level = 'Beginner'
   and (key_expressions is null or key_expressions::text in ('[]', 'null'));

update public.study_daily_content set phrase_munch_lessons = $j$[{"example":{"ko":"그 식당은 가격이 싼 편이에요.","en":"That restaurant is on the cheap side.","parts":[{"ko":"그","en":"that"},{"ko":"식당은","en":"restaurant + topic marker"},{"ko":"가격이","en":"price + subject marker"},{"ko":"싼","en":"cheap (싸다, modifier form)"},{"ko":"편이에요","en":"is on the ~ side, tends to be"}],"grammar_note":"-(으)ㄴ/는 편이다 softens a description: 싼 편이에요 = it is fairly cheap. Adjectives take -(으)ㄴ."},"practice":{"ko":"그 카페는 조용한 편이에요.","en":"That café tends to be quiet.","parts":[{"ko":"그","en":"that"},{"ko":"카페는","en":"café + topic marker"},{"ko":"조용한","en":"quiet (조용하다, modifier form)"},{"ko":"편이에요","en":"tends to be"}],"choices":["그 카페는 조용한 편이에요.","그 카페는 조용하는 편이에요.","그 카페는 조용한 편이었어요.","그 카페는 조용한 편을 해요."]}},{"example":{"ko":"꼭 한번 가 보세요.","en":"Be sure to go there sometime.","parts":[{"ko":"꼭","en":"definitely, be sure to"},{"ko":"한번","en":"once, sometime (give it a try)"},{"ko":"가","en":"go (가다 + 아)"},{"ko":"보세요","en":"try ~ing (polite suggestion)"}],"grammar_note":"-아/어 보세요 recommends trying something: 가 보세요 = try going there. 꼭 makes the recommendation stronger."},"practice":{"ko":"비빔밥을 꼭 먹어 보세요.","en":"Be sure to try the bibimbap.","parts":[{"ko":"비빔밥을","en":"bibimbap + object marker"},{"ko":"꼭","en":"be sure to"},{"ko":"먹어","en":"eat (먹다 + 어)"},{"ko":"보세요","en":"try ~ing (polite suggestion)"}],"choices":["비빔밥을 꼭 먹어 보세요.","비빔밥을 꼭 먹고 보세요.","비빔밥을 꼭 먹어 봤어요.","비빔밥이 꼭 먹어 보세요."]}},{"example":{"ko":"음식이 신선하기 때문에 손님이 많아요.","en":"There are lots of customers because the food is fresh.","parts":[{"ko":"음식이","en":"food + subject marker"},{"ko":"신선하기","en":"being fresh (신선하다 + 기)"},{"ko":"때문에","en":"because of"},{"ko":"손님이","en":"customers + subject marker"},{"ko":"많아요","en":"there are many"}],"grammar_note":"-기 때문에 states a clear reason, useful when explaining a recommendation: 신선하기 때문에 = because it is fresh."},"practice":{"ko":"직원들이 친절하기 때문에 자주 가요.","en":"I go there often because the staff are kind.","parts":[{"ko":"직원들이","en":"staff + subject marker"},{"ko":"친절하기","en":"being kind (친절하다 + 기)"},{"ko":"때문에","en":"because of"},{"ko":"자주","en":"often"},{"ko":"가요","en":"go"}],"choices":["직원들이 친절하기 때문에 자주 가요.","직원들이 친절한 때문에 자주 가요.","직원들이 친절하기 때문에 자주 가세요.","직원들이 친절하기 때문에 자주 갔어요."]}}]$j$
 where scheduled_date = '2026-10-26' and level = 'Intermediate'
   and (phrase_munch_lessons is null or phrase_munch_lessons::text in ('[]', 'null'));
update public.study_daily_content set key_expressions = $j$[{"ko":"~을/를 추천해요","rom":"~eul/reul chucheonhaeyo","en":"I recommend ~","parts":[{"ko":"~을/를","en":"object marker on the place or dish"},{"ko":"추천해요","en":"recommend"}],"examples":[{"ko":"저는 학교 앞 분식집을 추천해요.","en":"I recommend the snack bar in front of my school."},{"ko":"이 집에서는 김치찌개를 추천해요.","en":"At this place, I recommend the kimchi stew."}]},{"ko":"~(으)ㄴ/는 편이에요","rom":"~(eu)n/neun pyeonieyo","en":"it is fairly ~ / it tends to be ~","parts":[{"ko":"~(으)ㄴ/는","en":"modifier: adjectives take -(으)ㄴ, verbs take -는"},{"ko":"편이에요","en":"is on the ~ side"}],"examples":[{"ko":"그 식당은 가격이 싼 편이에요.","en":"That restaurant is on the cheap side."},{"ko":"주말에는 손님이 많은 편이에요.","en":"It tends to be busy on weekends."}]},{"ko":"~기 때문에","rom":"~gi ttaemune","en":"because ~","parts":[{"ko":"~기","en":"turns the verb or adjective into a noun"},{"ko":"때문에","en":"because of"}],"examples":[{"ko":"음식이 신선하기 때문에 자주 가요.","en":"I go often because the food is fresh."},{"ko":"분위기가 좋기 때문에 데이트하기 좋아요.","en":"The atmosphere is nice, so it is a good place for a date."}]},{"ko":"~(으)로 유명해요","rom":"~(eu)ro yumyeonghaeyo","en":"it is famous for ~","parts":[{"ko":"~(으)로","en":"for (what it is known for): 로 after a vowel or ㄹ, 으로 after other consonants"},{"ko":"유명해요","en":"is famous"}],"examples":[{"ko":"그 집은 냉면으로 유명해요.","en":"That place is famous for its naengmyeon."},{"ko":"이 동네는 맛집으로 유명해요.","en":"This neighborhood is famous for its great restaurants."}]},{"ko":"~아/어 보세요","rom":"~a/eo boseyo","en":"try ~ (a recommendation)","parts":[{"ko":"~아/어","en":"verb + 아/어"},{"ko":"보세요","en":"try ~ing (polite suggestion)"}],"examples":[{"ko":"꼭 한번 가 보세요.","en":"Be sure to go there sometime."},{"ko":"그 집 갈비를 꼭 먹어 보세요.","en":"Be sure to try their galbi."}]},{"ko":"~에 비해","rom":"~e bihae","en":"compared to ~ / for ~","parts":[{"ko":"~에","en":"to (the thing you compare with)"},{"ko":"비해","en":"compared (비하다 + 여)"}],"examples":[{"ko":"가격에 비해 양이 많아요.","en":"The portions are big for the price."},{"ko":"다른 식당에 비해 조용해요.","en":"It is quiet compared to other restaurants."}]}]$j$
 where scheduled_date = '2026-10-26' and level = 'Intermediate'
   and (key_expressions is null or key_expressions::text in ('[]', 'null'));

update public.study_daily_content set phrase_munch_lessons = $j$[{"example":{"ko":"제 취미는 요리예요.","en":"My hobby is cooking.","parts":[{"ko":"제","en":"my (polite)"},{"ko":"취미는","en":"hobby + topic marker"},{"ko":"요리예요","en":"is cooking"}],"grammar_note":"제 취미는 N이에요/예요 = \"My hobby is N\". 예요 after a vowel (요리예요), 이에요 after a consonant (등산이에요)."},"practice":{"ko":"제 취미는 등산이에요.","en":"My hobby is hiking.","parts":[{"ko":"제","en":"my (polite)"},{"ko":"취미는","en":"hobby + topic marker"},{"ko":"등산이에요","en":"is hiking"}],"choices":["제 취미는 등산이에요.","제 취미는 등산예요.","제 취미를 등산이에요.","제 취미는 등산이 아니에요."]}},{"example":{"ko":"주말에 자전거를 타요.","en":"I ride my bike on weekends.","parts":[{"ko":"주말에","en":"on weekends (에 = at / on, for time)"},{"ko":"자전거를","en":"bicycle + object marker"},{"ko":"타요","en":"ride"}],"grammar_note":"에 after a time word means \"at / on / in\": 주말에 = on weekends, 저녁에 = in the evening."},"practice":{"ko":"저녁에 책을 읽어요.","en":"I read books in the evening.","parts":[{"ko":"저녁에","en":"in the evening"},{"ko":"책을","en":"book + object marker"},{"ko":"읽어요","en":"read"}],"choices":["저녁에 책을 읽어요.","저녁에서 책을 읽어요.","저녁에 책이 읽어요.","저녁에 책을 읽었어요."]}},{"example":{"ko":"저는 노래하는 것을 좋아해요.","en":"I like singing.","parts":[{"ko":"저는","en":"I + topic marker"},{"ko":"노래하는","en":"singing (노래하다 + 는)"},{"ko":"것을","en":"the act of + object marker"},{"ko":"좋아해요","en":"like"}],"grammar_note":"V-는 것 turns a verb into \"doing V\": 노래하는 것을 좋아해요 = I like singing."},"practice":{"ko":"저는 사진 찍는 것을 좋아해요.","en":"I like taking pictures.","parts":[{"ko":"저는","en":"I + topic marker"},{"ko":"사진","en":"photo"},{"ko":"찍는","en":"taking (찍다 + 는)"},{"ko":"것을","en":"the act of + object marker"},{"ko":"좋아해요","en":"like"}],"choices":["저는 사진 찍는 것을 좋아해요.","저는 사진 찍는 것이 좋아해요.","저는 사진 찍다 것을 좋아해요.","저는 사진 찍는 것을 싫어해요."]}}]$j$
 where scheduled_date = '2026-11-02' and level = 'Starter'
   and (phrase_munch_lessons is null or phrase_munch_lessons::text in ('[]', 'null'));
update public.study_daily_content set key_expressions = $j$[{"ko":"제 취미는 ~","rom":"je chwimineun ~","en":"my hobby is ~","parts":[{"ko":"제","en":"my (polite)"},{"ko":"취미는","en":"hobby + topic marker"},{"ko":"~","en":"the hobby + 이에요/예요"}],"examples":[{"ko":"제 취미는 요리예요.","en":"My hobby is cooking."},{"ko":"제 취미는 등산이에요.","en":"My hobby is hiking."}]},{"ko":"~을/를 좋아해요","rom":"~eul/reul joahaeyo","en":"I like ~","parts":[{"ko":"~을/를","en":"object marker on the thing you like"},{"ko":"좋아해요","en":"like"}],"examples":[{"ko":"저는 음악을 좋아해요.","en":"I like music."},{"ko":"동생은 축구를 좋아해요.","en":"My younger sibling likes soccer."}]},{"ko":"~는 것을 좋아해요","rom":"~neun geoseul joahaeyo","en":"I like doing ~","parts":[{"ko":"~는","en":"verb + 는 (doing)"},{"ko":"것을","en":"the act of + object marker"},{"ko":"좋아해요","en":"like"}],"examples":[{"ko":"저는 그림 그리는 것을 좋아해요.","en":"I like drawing."},{"ko":"저는 춤추는 것을 좋아해요.","en":"I like dancing."}]},{"ko":"주말에 ~","rom":"jumare ~","en":"on weekends, I ~","parts":[{"ko":"주말","en":"weekend"},{"ko":"에","en":"on (time marker)"},{"ko":"~","en":"what you do"}],"examples":[{"ko":"주말에 자전거를 타요.","en":"I ride my bike on weekends."},{"ko":"주말에 친구하고 영화를 봐요.","en":"On weekends I watch movies with a friend."}]},{"ko":"~을/를 잘해요","rom":"~eul/reul jalhaeyo","en":"I am good at ~","parts":[{"ko":"~을/를","en":"object marker on the activity"},{"ko":"잘해요","en":"do well, be good at"}],"examples":[{"ko":"저는 요리를 잘해요.","en":"I am good at cooking."},{"ko":"동생은 수영을 잘해요.","en":"My younger sibling is good at swimming."}]},{"ko":"시간이 있을 때 ~","rom":"sigani isseul ttae ~","en":"when I have time, I ~","parts":[{"ko":"시간이","en":"time + subject marker"},{"ko":"있을 때","en":"when there is (있다 + 을 때)"},{"ko":"~","en":"what you do"}],"examples":[{"ko":"시간이 있을 때 책을 읽어요.","en":"When I have time, I read books."},{"ko":"시간이 있을 때 공원에서 산책해요.","en":"When I have time, I take a walk in the park."}]}]$j$
 where scheduled_date = '2026-11-02' and level = 'Starter'
   and (key_expressions is null or key_expressions::text in ('[]', 'null'));

update public.study_daily_content set phrase_munch_lessons = $j$[{"example":{"ko":"제가 가장 좋아하는 시간은 저녁이에요.","en":"My favorite time of day is the evening.","parts":[{"ko":"제가","en":"I (polite) + subject marker"},{"ko":"가장","en":"the most"},{"ko":"좋아하는","en":"that (I) like (좋아하다 + 는)"},{"ko":"시간은","en":"time + topic marker"},{"ko":"저녁이에요","en":"is the evening"}],"grammar_note":"V-는 + noun describes the noun: 좋아하는 시간 = the time I like. 가장 = the most."},"practice":{"ko":"제가 가장 좋아하는 음식은 비빔밥이에요.","en":"The food I like the most is bibimbap.","parts":[{"ko":"제가","en":"I (polite) + subject marker"},{"ko":"가장","en":"the most"},{"ko":"좋아하는","en":"that (I) like"},{"ko":"음식은","en":"food + topic marker"},{"ko":"비빔밥이에요","en":"is bibimbap"}],"choices":["제가 가장 좋아하는 음식은 비빔밥이에요.","제가 가장 좋아하다 음식은 비빔밥이에요.","제가 가장 좋아하는 음식을 비빔밥이에요.","제가 가장 좋아한 음식은 비빔밥이었어요."]}},{"example":{"ko":"커피를 마시면서 음악을 들어요.","en":"I listen to music while drinking coffee.","parts":[{"ko":"커피를","en":"coffee + object marker"},{"ko":"마시면서","en":"while drinking (마시다 + 면서)"},{"ko":"음악을","en":"music + object marker"},{"ko":"들어요","en":"listen (듣다 → 들어요)"}],"grammar_note":"-(으)면서 means \"while\": doing two things at the same time. 마시면서 = while drinking."},"practice":{"ko":"저녁을 먹으면서 텔레비전을 봐요.","en":"I watch TV while eating dinner.","parts":[{"ko":"저녁을","en":"dinner + object marker"},{"ko":"먹으면서","en":"while eating (먹다 + 으면서)"},{"ko":"텔레비전을","en":"TV + object marker"},{"ko":"봐요","en":"watch"}],"choices":["저녁을 먹으면서 텔레비전을 봐요.","저녁을 먹면서 텔레비전을 봐요.","저녁을 먹으면서 텔레비전이 봐요.","저녁을 먹으면서 텔레비전을 봤어요."]}},{"example":{"ko":"자기 전에 책을 읽어요.","en":"I read before going to sleep.","parts":[{"ko":"자기","en":"sleeping (자다 + 기)"},{"ko":"전에","en":"before"},{"ko":"책을","en":"book + object marker"},{"ko":"읽어요","en":"read"}],"grammar_note":"V-기 전에 means \"before V-ing\": 자기 전에 = before going to sleep."},"practice":{"ko":"운동하기 전에 물을 마셔요.","en":"I drink water before I exercise.","parts":[{"ko":"운동하기","en":"exercising (운동하다 + 기)"},{"ko":"전에","en":"before"},{"ko":"물을","en":"water + object marker"},{"ko":"마셔요","en":"drink"}],"choices":["운동하기 전에 물을 마셔요.","운동한 전에 물을 마셔요.","운동하기 후에 물을 마셔요.","운동하기 전에 물이 마셔요."]}}]$j$
 where scheduled_date = '2026-11-02' and level = 'Beginner'
   and (phrase_munch_lessons is null or phrase_munch_lessons::text in ('[]', 'null'));
update public.study_daily_content set key_expressions = $j$[{"ko":"제가 가장 좋아하는 시간은 ~","rom":"jega gajang joahaneun siganeun ~","en":"my favorite time (of day) is ~","parts":[{"ko":"제가","en":"I (polite) + subject marker"},{"ko":"가장","en":"the most"},{"ko":"좋아하는","en":"that I like"},{"ko":"시간은","en":"time + topic marker"}],"examples":[{"ko":"제가 가장 좋아하는 시간은 저녁이에요.","en":"My favorite time of day is the evening."},{"ko":"제가 가장 좋아하는 시간은 점심시간이에요.","en":"My favorite time of day is lunchtime."}]},{"ko":"~(으)면서 음악을 들어요","rom":"~(eu)myeonseo eumageul deureoyo","en":"I listen to music while ~","parts":[{"ko":"~(으)면서","en":"while (doing ~)"},{"ko":"음악을","en":"music + object marker"},{"ko":"들어요","en":"listen (듣다 → 들어요)"}],"examples":[{"ko":"커피를 마시면서 음악을 들어요.","en":"I listen to music while drinking coffee."},{"ko":"산책하면서 음악을 들어요.","en":"I listen to music while taking a walk."}]},{"ko":"~기 전에","rom":"~gi jeone","en":"before ~ing","parts":[{"ko":"~기","en":"verb + 기"},{"ko":"전에","en":"before"}],"examples":[{"ko":"자기 전에 책을 읽어요.","en":"I read before going to sleep."},{"ko":"출근하기 전에 커피를 마셔요.","en":"I drink coffee before going to work."}]},{"ko":"~(으)ㄹ 때 기분이 좋아요","rom":"~(eu)l ttae gibuni joayo","en":"I feel good when ~","parts":[{"ko":"~(으)ㄹ 때","en":"when ~"},{"ko":"기분이","en":"mood + subject marker"},{"ko":"좋아요","en":"is good"}],"examples":[{"ko":"해가 질 때 기분이 좋아요.","en":"I feel good when the sun sets."},{"ko":"퇴근할 때 기분이 좋아요.","en":"I feel good when I leave work."}]},{"ko":"~이/가 제일 편해요","rom":"~i/ga jeil pyeonhaeyo","en":"~ is when I feel most relaxed","parts":[{"ko":"~이/가","en":"the time + subject marker"},{"ko":"제일","en":"the most"},{"ko":"편해요","en":"is comfortable, relaxed"}],"examples":[{"ko":"저는 밤이 제일 편해요.","en":"Night is when I feel most relaxed."},{"ko":"저는 집에 있을 때가 제일 편해요.","en":"I feel most relaxed when I am at home."}]},{"ko":"~에 일어나요","rom":"~e ireonayo","en":"I get up at ~","parts":[{"ko":"~에","en":"at (time marker)"},{"ko":"일어나요","en":"get up"}],"examples":[{"ko":"저는 보통 일곱 시에 일어나요.","en":"I usually get up at seven."},{"ko":"주말에는 열 시에 일어나요.","en":"On weekends I get up at ten."}]}]$j$
 where scheduled_date = '2026-11-02' and level = 'Beginner'
   and (key_expressions is null or key_expressions::text in ('[]', 'null'));

update public.study_daily_content set phrase_munch_lessons = $j$[{"example":{"ko":"저는 아침 루틴이 더 중요하다고 생각해요.","en":"I think the morning routine is more important.","parts":[{"ko":"저는","en":"I + topic marker"},{"ko":"아침","en":"morning"},{"ko":"루틴이","en":"routine + subject marker"},{"ko":"더","en":"more"},{"ko":"중요하다고","en":"that (it) is important (quoted)"},{"ko":"생각해요","en":"think"}],"grammar_note":"A-다고 생각해요 = \"I think (that) A\". Adjectives add -다고 to the dictionary form: 중요하다 → 중요하다고."},"practice":{"ko":"저는 잠이 더 중요하다고 생각해요.","en":"I think sleep is more important.","parts":[{"ko":"저는","en":"I + topic marker"},{"ko":"잠이","en":"sleep + subject marker"},{"ko":"더","en":"more"},{"ko":"중요하다고","en":"that (it) is important"},{"ko":"생각해요","en":"think"}],"choices":["저는 잠이 더 중요하다고 생각해요.","저는 잠이 더 중요한다고 생각해요.","저는 잠이 더 중요해서 생각해요.","저는 잠이 더 중요하다고 생각했어요."]}},{"example":{"ko":"일찍 자면 아침이 편해요.","en":"If I go to bed early, my mornings are easy.","parts":[{"ko":"일찍","en":"early"},{"ko":"자면","en":"if (I) sleep (자다 + 면)"},{"ko":"아침이","en":"morning + subject marker"},{"ko":"편해요","en":"is comfortable, easy"}],"grammar_note":"-(으)면 = \"if / when\": 일찍 자면 = if I go to bed early. -면 after a vowel, -으면 after a consonant."},"practice":{"ko":"밤에 커피를 마시면 잠을 못 자요.","en":"If I drink coffee at night, I can't sleep.","parts":[{"ko":"밤에","en":"at night"},{"ko":"커피를","en":"coffee + object marker"},{"ko":"마시면","en":"if (I) drink (마시다 + 면)"},{"ko":"잠을","en":"sleep + object marker"},{"ko":"못 자요","en":"can't sleep"}],"choices":["밤에 커피를 마시면 잠을 못 자요.","밤에 커피를 마셔면 잠을 못 자요.","밤에 커피를 마시면 잠을 안 못 자요.","밤에 커피를 마시면 잠을 못 잤어요."]}},{"example":{"ko":"저녁에는 일찍 자는 게 좋아요.","en":"In the evening, it is good to go to bed early.","parts":[{"ko":"저녁에는","en":"in the evening (는 = as for)"},{"ko":"일찍","en":"early"},{"ko":"자는","en":"sleeping (자다 + 는)"},{"ko":"게","en":"the act of (것이, spoken)"},{"ko":"좋아요","en":"is good"}],"grammar_note":"V-는 게 좋아요 gives advice: \"it is good to V\". 게 is the spoken short form of 것이."},"practice":{"ko":"아침에 계획을 세우는 게 좋아요.","en":"It is good to make a plan in the morning.","parts":[{"ko":"아침에","en":"in the morning"},{"ko":"계획을","en":"plan + object marker"},{"ko":"세우는","en":"making (세우다 + 는; 계획을 세우다 = make a plan)"},{"ko":"게","en":"the act of (것이, spoken)"},{"ko":"좋아요","en":"is good"}],"choices":["아침에 계획을 세우는 게 좋아요.","아침에 계획을 세우다 게 좋아요.","아침에 계획이 세우는 게 좋아요.","아침에 계획을 세우는 게 좋았어요."]}}]$j$
 where scheduled_date = '2026-11-02' and level = 'Intermediate'
   and (phrase_munch_lessons is null or phrase_munch_lessons::text in ('[]', 'null'));
update public.study_daily_content set key_expressions = $j$[{"ko":"~다고 생각해요","rom":"~dago saenggakaeyo","en":"I think (that) ~","parts":[{"ko":"~다고","en":"quoted form: adjective + 다고 (action verbs take -ㄴ/는다고: 간다고, 먹는다고)"},{"ko":"생각해요","en":"think"}],"examples":[{"ko":"아침 루틴이 더 중요하다고 생각해요.","en":"I think the morning routine is more important."},{"ko":"저녁 시간이 하루를 정리하기에 좋다고 생각해요.","en":"I think the evening is a good time to wrap up the day."}]},{"ko":"~ 중에서","rom":"~ jungeseo","en":"between ~ / among ~","parts":[{"ko":"~","en":"the options (A와 B)"},{"ko":"중","en":"among, out of"},{"ko":"에서","en":"from"}],"examples":[{"ko":"아침과 저녁 중에서 아침을 더 좋아해요.","en":"Between morning and evening, I prefer the morning."},{"ko":"운동과 독서 중에서 뭐가 더 좋아요?","en":"Between exercise and reading, which do you like more?"}]},{"ko":"~(으)면 하루가 편해요","rom":"~(eu)myeon haruga pyeonhaeyo","en":"if ~, my day goes smoothly","parts":[{"ko":"~(으)면","en":"if ~"},{"ko":"하루가","en":"the day + subject marker"},{"ko":"편해요","en":"is easy, comfortable"}],"examples":[{"ko":"아침에 일찍 일어나면 하루가 편해요.","en":"If I wake up early, my day goes smoothly."},{"ko":"전날 밤에 미리 준비하면 하루가 편해요.","en":"If I get ready the night before, my day goes smoothly."}]},{"ko":"~는 게 좋아요","rom":"~neun ge joayo","en":"it is good to ~","parts":[{"ko":"~는","en":"verb + 는"},{"ko":"게","en":"the act of (것이, spoken)"},{"ko":"좋아요","en":"is good"}],"examples":[{"ko":"자기 전에는 휴대폰을 안 보는 게 좋아요.","en":"It is better not to look at your phone before bed."},{"ko":"아침에 물을 한 잔 마시는 게 좋아요.","en":"It is good to drink a glass of water in the morning."}]},{"ko":"~는 습관이 있어요","rom":"~neun seupgwani isseoyo","en":"I have a habit of ~","parts":[{"ko":"~는","en":"verb + 는"},{"ko":"습관이","en":"habit + subject marker"},{"ko":"있어요","en":"have"}],"examples":[{"ko":"저는 자기 전에 일기를 쓰는 습관이 있어요.","en":"I have a habit of writing in my diary before bed."},{"ko":"저는 아침마다 스트레칭을 하는 습관이 있어요.","en":"I have a habit of stretching every morning."}]},{"ko":"~ 덕분에","rom":"~ deokbune","en":"thanks to ~","parts":[{"ko":"~","en":"a noun (the good cause)"},{"ko":"덕분에","en":"thanks to"}],"examples":[{"ko":"규칙적인 생활 덕분에 건강해졌어요.","en":"Thanks to a regular routine, I became healthier."},{"ko":"아침 운동 덕분에 하루 종일 힘이 나요.","en":"Thanks to my morning exercise, I have energy all day."}]}]$j$
 where scheduled_date = '2026-11-02' and level = 'Intermediate'
   and (key_expressions is null or key_expressions::text in ('[]', 'null'));
